<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');include __DIR__.'/../../admin/controllers/Base.php';class Stock extends HRC_Controller{	public function __construct()	{		parent::__construct();		$this->load->library('google');	}	public function index()	{	}	public function get($code = 'HDC01', $material = 'NAT')	{		if( $material == 'all' )		{			$stocks = $this->google->stock($code, 'all');			echo "Product Code: $code <br>";			foreach ($stocks as $key => $stock)			{				echo "Stock $key Color: $stock <br>";			}			return;		}		if( $stock = $this->google->stock($code, $material) )		{			echo "product code : $code <br> Color : $material <br>Stock: ". $stock."<br>";			return $stock;		}		else{			echo "Product code is not found";			return false;		}	}	public function update($code = 'HDC01', $materials, $purchased = 1)	{		$this->load->library('order');		$ref = $this->order->createRefId( Transaction::orderBy('id', 'desc')->first()->id );		foreach ( explode('-', $materials) as $key => $material)		{			if( $material != '' )			{				$data = $this->google->inventory('update', [																					'code' => $code, 																					'material' => $material,																					'purchased' => $purchased, 																					'noRef' => $ref,																					'customer' => 'system'																				]);				vd($data);			}		}	}}